    "也可以在表格里直接输入颜色，会自动套用颜色代码和统一泰文。颜色表在设置页修改。SKU = 产品编码-颜色代码-规格代码。导出过 Lazada 后 SKU 锁定。": "พิมพ์สีในตารางเองก็ได้ ระบบจะใส่รหัสสีและชื่อภาษาไทยให้ แก้ตารางสีได้ในหน้าตั้งค่า SKU = รหัสสินค้า-รหัสสี-รหัสขนาด หลังส่งออก Lazada แล้ว SKU จะถูกล็อก",
    "预览颜色：": "สีที่แสดง:",
    "AI 打印建议 + 产品描述": "AI แนะนำการพิมพ์ + คำอธิบายสินค้า",
    "AI 会分析模型（6 个摆放方向的悬空面积、底面接触、尺寸）和渲染图，结合你的提示词，给出：给客户看的用途/卖点描述、建议材质、摆放方向、层高、壁数、填充率、支撑和注意事项。没有模型时按产品信息和第一张图片分析。": "AI จะวิเคราะห์โมเดล (พื้นที่ส่วนยื่นของการวาง 6 แบบ, พื้นที่ฐาน, ขนาด) และรูปเรนเดอร์ ร่วมกับคำสั่งของคุณ แล้วให้: คำอธิบายการใช้งาน/จุดขายสำหรับลูกค้า, วัสดุที่แนะนำ, ทิศทางการวาง, ความสูงชั้น, จำนวนผนัง, เปอร์เซ็นต์เติมเนื้อใน, ซัพพอร์ต และข้อควรระวัง ถ้าไม่มีโมเดลจะวิเคราะห์จากข้อมูลสินค้าและรูปแรก",
    "提示词（可空）：例如 放在车里用、要结实耐用、给小孩玩、要软一点、户外晒太阳、要好看的外观面…": "คำสั่ง (เว้นว่างได้): เช่น ใช้ในรถ, ต้องแข็งแรงทนทาน, ให้เด็กเล่น, อยากให้นิ่ม, ตากแดดกลางแจ้ง, ต้องการผิวด้านนอกสวย…",
    "AI 分析并生成建议": "ให้ AI วิเคราะห์และแนะนำ",
    "AI 分析中（约 20-60 秒）…": "AI กำลังวิเคราะห์ (ประมาณ 20-60 วินาที)…",
