    "「每小时克数」用于估算打印时长。OrcaSlicer 自动切片会用下面三项配置：点「自动匹配配置」会按打印机名称自动选好 OrcaSlicer 自带的配置（不需要先在 OrcaSlicer 里保存预设）；也可以在输入框里点一下从列表里选。产品材质不是 PLA 时，会自动换成对应材质的耗材配置。估算校准系数：": "「กรัมต่อชั่วโมง」ใช้ประมาณเวลาพิมพ์ การสไลซ์อัตโนมัติด้วย OrcaSlicer ใช้ 3 โปรไฟล์ด้านล่าง: กด 「จับคู่โปรไฟล์อัตโนมัติ」 ระบบจะเลือกโปรไฟล์ในตัวของ OrcaSlicer ตามชื่อเครื่องพิมพ์ (ไม่ต้องบันทึกพรีเซ็ตใน OrcaSlicer ก่อน) หรือคลิกในช่องเพื่อเลือกจากรายการ ถ้าวัสดุสินค้าไม่ใช่ PLA จะเปลี่ยนเป็นโปรไฟล์ฟิลาเมนต์ของวัสดุนั้นให้อัตโนมัติ ตัวปรับเทียบค่าประมาณ: ",
