    "灰色的词还没用上：改完关键词后点「AI 生成文案」重新生成，会尽量都用上（标题放最重要的，其他自然地写进详情）。": "คำสีเทายังไม่ได้ใช้: แก้คีย์เวิร์ดแล้วกด 「AI เขียนรายละเอียด」 ใหม่ ระบบจะพยายามใช้ให้ครบ (คำสำคัญที่สุดใส่ในชื่อ ที่เหลือเขียนในรายละเอียดอย่างเป็นธรรมชาติ)",
    "重新扩展会替换现在的关键词列表（自己添加的会保留），继续？": "ขยายใหม่จะแทนที่รายการคีย์เวิร์ดเดิม (คำที่เพิ่มเองจะยังอยู่) ดำเนินการต่อ?",
    "关键词已扩展，并补进①的关键词。下一步点「AI 生成文案」": "ขยายคีย์เวิร์ดแล้ว และเพิ่มลงในคีย์เวิร์ดของ ① แล้ว ขั้นต่อไปกด 「AI เขียนรายละเอียด」",
    "泰文标题（Lazada）": "ชื่อสินค้าภาษาไทย (Lazada)",
    "泰文标题（Shopee，最多 120 字符，空=用 Lazada 标题）": "ชื่อสินค้าภาษาไทย (Shopee สูงสุด 120 ตัวอักษร ว่าง = ใช้ชื่อของ Lazada)",
    "Shopee 标签（加在 Shopee 详情最后，会被搜索，最多 18 个）": "แท็ก Shopee (ต่อท้ายรายละเอียด Shopee ค้นหาได้ สูงสุด 18 แท็ก)",
    "（需 20-120）": " (ต้อง 20-120)",
    "程序已更新，但后台还在运行旧版本（v": "โปรแกรมอัปเดตแล้ว แต่เบื้องหลังยังรันเวอร์ชันเก่า (v",
    "）。请关闭所有黑色窗口，再重新双击 2_start.bat。": ") กรุณาปิดหน้าต่างสีดำทั้งหมด แล้วดับเบิลคลิก 2_start.bat ใหม่",
