    "（不含产品，所以不会画错你的产品）：": " (ไม่มีสินค้าในภาพ จึงไม่วาดสินค้าของคุณผิด):",
    "生成选中的背景": "สร้างพื้นหลังที่เลือก",
    "背景库是所有产品共用的。两种方式添加：①用手机拍自己的书桌、书架、床头柜、客厅茶几（台面空着、光线柔和、正方形构图）后上传，最真实也免费；②下面让 AI 生成电商常用的空背景，只生成一次，以后所有产品都能用（每张约 0.4-2 铢）。": "คลังพื้นหลังใช้ร่วมกันทุกสินค้า เพิ่มได้ 2 วิธี: ① ใช้มือถือถ่ายโต๊ะทำงาน ชั้นหนังสือ โต๊ะข้างเตียง โต๊ะกลางห้องรับแขก (พื้นโต๊ะว่าง แสงนุ่ม ถ่ายแบบสี่เหลี่ยมจัตุรัส) แล้วอัปโหลด สมจริงที่สุดและฟรี ② ให้ AI สร้างพื้นหลังว่างแบบที่ร้านค้าออนไลน์นิยมด้านล่าง สร้างครั้งเดียวใช้ได้กับทุกสินค้า (รูปละประมาณ 0.4-2 บาท)",
    "背景库还是空的：上传自己拍的背景照片，或在下面用 AI 生成电商常用背景。": "คลังพื้นหลังยังว่าง: อัปโหลดรูปพื้นหลังที่ถ่ายเอง หรือให้ AI สร้างพื้นหลังด้านล่าง",
    "请先点选要生成的背景（可多选）": "กรุณาเลือกพื้นหลังที่จะสร้างก่อน (เลือกได้หลายอัน)",
