    "AI 回复买家时只用这里的店铺政策、常见问答、产品库里的资料和订单信息，不会自己编价格和日期。员工发出去的回复会自动记下来，AI 下次参考。": "AI ตอบลูกค้าโดยใช้เฉพาะนโยบายร้าน คำถามที่พบบ่อย ข้อมูลสินค้า และข้อมูลออเดอร์ที่นี่ ไม่แต่งราคาหรือวันที่เอง คำตอบที่พนักงานส่งจริงจะถูกบันทึกให้ AI ใช้อ้างอิงครั้งต่อไป",
    "浏览器扩展（在卖家中心聊天页面直接用 AI）": "ส่วนขยายเบราว์เซอร์ (ใช้ AI ในหน้าแชท Seller Center ได้เลย)",
    "⬇ 下载扩展": "⬇ ดาวน์โหลดส่วนขยาย",
    "下载后解压到一个固定的文件夹（不要删）。": "ดาวน์โหลดแล้วแตกไฟล์ไว้ในโฟลเดอร์ถาวร (ห้ามลบ)",
    "Chrome 地址栏打开 ": "เปิดในแถบที่อยู่ Chrome: ",
    " → 右上角打开「开发者模式」→「加载已解压的扩展程序」→ 选刚才解压的文件夹。": " → เปิด「Developer mode」มุมขวาบน →「Load unpacked」→ เลือกโฟลเดอร์ที่แตกไว้",
    "老板在 系统 → 设置 → AI 与对接 → API 密钥 里给每个员工新建一个密钥。": "เจ้าของสร้าง API Key ให้พนักงานคนละอันที่ ระบบ → ตั้งค่า → บัญชีและสิทธิ์ → API Key",
    "点 Chrome 右上角的扩展图标：填软件地址（例如 ": "กดไอคอนส่วนขยายมุมขวาบนของ Chrome: ใส่ที่อยู่โปรแกรม (เช่น ",
    "）和密钥，选面板语言，点「保存并测试」。": ") และคีย์ เลือกภาษา แล้วกด「บันทึกและทดสอบ」",
    "打开 Lazada / Shopee / TikTok 卖家中心的聊天页面，右上角有「💬 AI」按钮：读取对话 → 检查回复 → 填入回复框 → 在平台按发送。": "เปิดหน้าแชทใน Seller Center ของ Lazada / Shopee / TikTok จะมีปุ่ม「💬 AI」มุมขวาบน: อ่านแชท → ตรวจคำตอบ → ใส่ในช่องตอบ → กดส่งในแพลตฟอร์ม",
    "每个店铺用自己的浏览器窗口登录（多个店铺可以用 Chrome 的不同「用户」）。账号密码只在浏览器里，扩展不会读取。勾选「自动」后，买家发新消息时会自动读取并写好回复草稿，仍然由员工按发送。": "แต่ละร้านล็อกอินในหน้าต่างเบราว์เซอร์ของตัวเอง (หลายร้านใช้ Chrome คนละโปรไฟล์ได้) รหัสผ่านอยู่แค่ในเบราว์เซอร์ ส่วนขยายไม่อ่าน ถ้าติ๊ก「อัตโนมัติ」เมื่อลูกค้าส่งข้อความใหม่จะอ่านและร่างคำตอบให้ทันที แต่พนักงานยังต้องกดส่งเอง",
