    "装了扩展，员工可以在 Lazada / Shopee / TikTok 卖家中心的聊天页面直接用 AI 读取消息、写回复（手动 / 半自动 / 全自动）。每个员工用自己的密钥连接本系统。": "ติดตั้งส่วนขยายแล้ว พนักงานใช้ AI อ่านข้อความและเขียนคำตอบในหน้าแชท Seller Center ของ Lazada / Shopee / TikTok ได้เลย (ด้วยตนเอง / กึ่งอัตโนมัติ / อัตโนมัติ) พนักงานแต่ละคนใช้คีย์ของตัวเองเชื่อมต่อระบบ",
    "密钥由老板生成，请向老板要你自己的密钥。": "คีย์สร้างโดยเจ้าของ กรุณาขอคีย์ของคุณจากเจ้าของ",
    "⬆ 上传电脑上切好的文件（可多选）": "⬆ อัปโหลดไฟล์ที่สไลซ์จากคอมพิวเตอร์ (เลือกได้หลายไฟล์)",
    "没有 3D 模型，可以直接上传电脑上切好的文件 ↓": "ไม่มีโมเดล 3D อัปโหลดไฟล์ที่สไลซ์จากคอมพิวเตอร์ได้เลย ↓",
    "自动识别打印机": "ตรวจจับเครื่องพิมพ์อัตโนมัติ",
    "用于": "ใช้กับ ",
    "Bambu Studio / OrcaSlicer 用「导出切片文件（Export plate sliced file）」得到 .gcode.3mf；Creality Print 导出 .gcode。": "Bambu Studio / OrcaSlicer ใช้「Export plate sliced file」จะได้ไฟล์ .gcode.3mf ส่วน Creality Print ส่งออกเป็น .gcode ",
    "打印机和一盘几个会从文件里自动认出来，认不出时再手动选。上传后是草稿，在 3D 切片预览里检查后复核。": "ระบบจะอ่านเครื่องพิมพ์และจำนวนต่อถาดจากไฟล์อัตโนมัติ ถ้าอ่านไม่ได้ค่อยเลือกเอง อัปโหลดแล้วเป็นแบบร่าง ตรวจในพรีวิวสไลซ์ 3D แล้วค่อยยืนยัน",
    "上传电脑上切好的文件，打印机和一盘几个自动识别": "อัปโหลดไฟล์ที่สไลซ์จากคอมพิวเตอร์ ตรวจจับเครื่องพิมพ์และจำนวนต่อถาดอัตโนมัติ",
    "⬆ 上传切片文件": "⬆ อัปโหลดไฟล์สไลซ์",
    "⬆ 批量上传切片文件": "⬆ อัปโหลดไฟล์สไลซ์หลายไฟล์",
    "所有产品的 3D 模型文件和切片文件都在这里：预览、下载、替换、恢复旧版本。批量上传模型或切片文件时，文件名以产品编号开头就能自动对应（例如 3DP0001.stl、3DP0001_K1Max_x6.gcode.3mf）；切片文件的打印机和一盘几个会从文件里自动认出来。也可以在每个产品那一行点「⬆ 上传切片文件」。": "ไฟล์โมเดล 3D และไฟล์สไลซ์ของทุกสินค้าอยู่ที่นี่: พรีวิว ดาวน์โหลด แทนที่ กู้คืนเวอร์ชันเก่า เวลาอัปโหลดหลายไฟล์ ให้ชื่อไฟล์ขึ้นต้นด้วยรหัสสินค้าจะจับคู่ให้อัตโนมัติ (เช่น 3DP0001.stl, 3DP0001_K1Max_x6.gcode.3mf) ไฟล์สไลซ์จะอ่านเครื่องพิมพ์และจำนวนต่อถาดจากไฟล์อัตโนมัติ หรือกด「⬆ อัปโหลดไฟล์สไลซ์」ในแถวของแต่ละสินค้าก็ได้",
    "文件名里没有找到产品编号（文件名要以产品编号开头，例如 3DP0001_xxx.gcode.3mf）": "ไม่พบรหัสสินค้าในชื่อไฟล์ (ชื่อไฟล์ต้องขึ้นต้นด้วยรหัสสินค้า เช่น 3DP0001_xxx.gcode.3mf)",
    "。请在 3D 切片预览里检查后复核": " กรุณาตรวจในพรีวิวสไลซ์ 3D แล้วยืนยัน",
    "。都是草稿，检查后复核": " ทั้งหมดเป็นแบบร่าง ตรวจแล้วค่อยยืนยัน",
