    "设置 → 生产「手动选择程序」；NAS 版第一次启动会自动安装": "หน้าตั้งค่า「เลือกโปรแกรมเอง」; เวอร์ชัน NAS ติดตั้งให้ตอนเปิดครั้งแรก",
