    "设置 → 生产 → 打印机：点「自动匹配配置」": "หน้าตั้งค่า → เครื่องพิมพ์: กด「จับคู่โปรไฟล์อัตโนมัติ」",
    "（设置里存的配置在这台机器上找不到，已自动改用匹配的）": " (ไม่พบโปรไฟล์ที่บันทึกไว้ในเครื่องนี้ ใช้โปรไฟล์ที่จับคู่อัตโนมัติแทน)",
