    "已设置 Telegram": "ตั้งค่า Telegram แล้ว",
    "没有设置，超时没回复只在系统里提醒": "ยังไม่ได้ตั้งค่า ถ้าตอบช้าจะเตือนแค่ในระบบ",
    "客服 → 知识库与话术 → 店铺政策下面「手机提醒」": "แชทลูกค้า → คลังความรู้ → ใต้นโยบายร้าน「แจ้งเตือนมือถือ」",
    "在线升级": "อัปเกรดออนไลน์",
    "收到新版本的压缩包后，直接在这里上传就能升级，不用再到 NAS / 电脑里手动覆盖文件。": "ได้ไฟล์ zip เวอร์ชันใหม่แล้ว อัปโหลดที่นี่ก็อัปเกรดได้เลย ไม่ต้องไปทับไฟล์เองใน NAS / คอมพิวเตอร์ ",
    "Windows 版和 NAS 版的压缩包都可以用。升级前会自动备份当前程序（在「数据备份」文件夹里，名字以 app_v 开头），数据不会动。": "ใช้ได้ทั้ง zip เวอร์ชัน Windows และ NAS ก่อนอัปเกรดจะสำรองโปรแกรมปัจจุบันให้อัตโนมัติ (ในโฟลเดอร์สำรองข้อมูล ชื่อขึ้นต้นด้วย app_v) ข้อมูลไม่ถูกแตะ",
    "⬆ 选择升级包并升级": "⬆ เลือกไฟล์อัปเกรดแล้วอัปเกรด",
