    "请关闭黑色窗口，再双击 2_start.bat 重新启动，新版本才会生效。": "กรุณาปิดหน้าต่างดำ แล้วดับเบิลคลิก 2_start.bat ใหม่ เวอร์ชันใหม่จึงจะมีผล",
    "Windows 启动脚本（.bat）没有在线替换，不影响使用": "สคริปต์เริ่มโปรแกรมของ Windows (.bat) ไม่ได้แทนที่ออนไลน์ ไม่มีผลต่อการใช้งาน",
