    "采用率高、改得少的问题类型，可以放心在「自动回复」里打开全自动；被改得多的，看「学到的回复」找原因，补充到常见问答。": "ประเภทคำถามที่ใช้ร่าง AI ได้เลยบ่อยๆ เปิดอัตโนมัติเต็มรูปแบบได้ ส่วนที่ถูกแก้บ่อย ดู「คำตอบที่เรียนรู้」หาสาเหตุแล้วเพิ่มในคำถามที่พบบ่อย",
    "超时提醒（手机）": "แจ้งเตือนตอบช้า (มือถือ)",
    "买家消息超过设定的分钟数没回复：客服工作台和工作台首页标红；填了 Telegram 还会推送到手机（同一个买家只提醒一次，直到他再发新消息）。": "ข้อความผู้ซื้อที่ไม่ได้ตอบเกินจำนวนนาทีที่ตั้ง: จะเป็นสีแดงในหน้าแชทและแดชบอร์ด ถ้ากรอก Telegram จะส่งแจ้งเตือนไปมือถือด้วย (ผู้ซื้อคนเดิมเตือนครั้งเดียวจนกว่าจะส่งข้อความใหม่) ",
    "设置方法：① 手机装 Telegram，搜索 @BotFather，发 /newbot 按提示建一个机器人，复制它给的 token；② 给你的新机器人发一句 hi；③ 把 token 填在下面，点「自动获取 chat id」；④ 保存后点「发送测试」。": "วิธีตั้งค่า: ① ติดตั้ง Telegram ค้นหา @BotFather ส่ง /newbot ทำตามขั้นตอนสร้างบอท คัดลอก token ② ส่งคำว่า hi ให้บอทใหม่ ③ ใส่ token ด้านล่าง กด「ดึง chat id อัตโนมัติ」 ④ บันทึกแล้วกด「ส่งทดสอบ」",
