    "已内置 3D 打印网店常见情况的标准话术（现货与 24–48 小时发货时效、材料与耐热、纹路色差、定制刻字、版权、批发、物流、改单取消、破损少件发错、退款、差评、平台规则等）。可以直接改成你们自己的说法；AI 回复时会参考。": "มีคำตอบมาตรฐานสำหรับร้าน 3D พิมพ์ในสถานการณ์ทั่วไปแล้ว (มีของและจัดส่งภายใน 24–48 ชม. วัสดุและความทนร้อน ลายเส้นและสีเพี้ยน สั่งทำใส่ชื่อ ลิขสิทธิ์ ราคาส่ง ขนส่ง แก้/ยกเลิกออเดอร์ ของเสียหาย/ขาด/ส่งผิด คืนเงิน รีวิวไม่ดี กฎแพลตฟอร์ม) แก้เป็นสำนวนของร้านเองได้ AI จะใช้อ้างอิงเวลาตอบ",
