    "同一机型的打印机共用切片文件和打印方案，排单时互为备用：一台停用或连不上，任务会自动转到其他机器。每台机器有一个": "เครื่องพิมพ์รุ่นเดียวกันใช้ไฟล์สไลซ์และแผนการพิมพ์ร่วมกัน และสำรองกันเวลาจัดคิว: ถ้าเครื่องหนึ่งหยุดใช้หรือเชื่อมต่อไม่ได้ งานจะย้ายไปเครื่องอื่นอัตโนมัติ แต่ละเครื่องมี",
